125	func removeContents(dir string) error {
126		d, err := os.Open(filepath.Clean(dir))
127		if err != nil {
128			return fmt.Errorf("removeContents: %w", err)
129		}
130	
131		defer func() {
132			if err = d.Close(); err != nil {
133				panic(err)
134			}
135		}()
136	
137		names, err := d.Readdirnames(-1)
138		if err != nil {
139			return fmt.Errorf("removeContents %w", err)
140		}
141	
142		for _, name := range names {
143			if err = os.RemoveAll(filepath.Clean(filepath.Join(dir, name))); err != nil {
144				return fmt.Errorf("removeContents %w", err)
145			}
146		}
147	
148		return nil
149	}
