151	func preflight() {
152		var err error
153	
154		// prepare clean backup directory
155		bud := os.Getenv(envGitBackupDir)
156	
157		// if path not provided, create one
158		if bud == "" {
159			bud, err = os.MkdirTemp(os.TempDir(), "sobabackup-*")
160			if err != nil {
161				panic(err)
162			}
163	
164			_ = os.Setenv(envGitBackupDir, bud)
165	
166			return
167		}
168	
169		_, err = os.Stat(filepath.Clean(bud))
170		if os.IsNotExist(err) {
171			if err = os.MkdirAll(filepath.Clean(bud), 0o700); err != nil {
172				panic(err)
173			}
174	
175			return
176		}
177	
178		// clean out existing backup directory
179		if err = removeContents(bud); err != nil {
180			panic(err)
181		}
182	}
